AUTEURS = [
 dict(name="Montesquieu", dates="1689-1755", courant="Lumières", chapters=[24],
      idea="Le « doux commerce » : l’interdépendance commerciale rend la guerre plus coûteuse donc moins probable",
      oeuvres=["De l’esprit des lois (1748)"],
      detail="Montesquieu écrit que « partout où il y a du commerce, il y a des mœurs douces » et souligne que deux nations qui commercent deviennent réciproquement dépendantes. Le mécanisme est explicite : le commerce crée de l’interdépendance, l’interdépendance élève le coût économique d’un conflit, et ce coût agit comme une incitation à la paix. C’est la matrice intellectuelle de la construction européenne, et notamment de la CECA en 1951.",
      phrase="Montesquieu fournit l’argument fondateur de la mondialisation heureuse : le commerce pacifie moins par vertu que par calcul, puisqu’il rend la guerre économiquement coûteuse pour celui qui la déclenche."),
 dict(name="Karl Marx", dates="1818-1883", courant="Marxiste", chapters=[24],
      idea="Les interdépendances internationales sont asymétriques et peuvent devenir des rapports de domination",
      oeuvres=["Discours sur le libre-échange (1848)"],
      detail="Pour Marx et les analyses marxistes, les échanges internationaux ne bénéficient pas identiquement à tous les pays : la répartition des gains est inégale, certains pays captant l’essentiel du surplus tandis que d’autres peuvent être perdants. L’interdépendance cesse alors d’être synonyme de sécurité et devient une source de dépendance et de vulnérabilité. Cette lecture, longtemps minoritaire pendant l’hypermondialisation, retrouve une actualité directe avec l’arsenalisation contemporaine des relations économiques.",
      phrase="Marx fournit le contrepoint exact de Montesquieu : lorsque l’échange est asymétrique, l’interdépendance ne pacifie pas, elle institue une domination que le plus fort peut ensuite instrumentaliser."),
 dict(name="Edward Luttwak", dates="1942-", courant="Géoéconomie", chapters=[24],
      idea="Après la guerre froide, la rivalité de puissance se déplace du terrain militaire vers le terrain économique",
      oeuvres=["« From Geopolitics to Geo-Economics: Logic of Conflict, Grammar of Commerce » (1990)"],
      detail="Au lendemain de la chute du mur de Berlin, Luttwak soutient que la disparition de l’affrontement militaire entre les deux blocs ne signifie pas la disparition de la rivalité entre grandes puissances : celle-ci change simplement de forme. Les États rechercheront désormais la puissance par le commerce, les investissements et la maîtrise des technologies. La formule « logique du conflit, grammaire du commerce » résume ce transfert : les objectifs restent stratégiques, seuls les instruments deviennent économiques.",
      phrase="Luttwak annonce dès 1990 ce que les droits de douane américains contemporains réalisent : une politique commerciale qui ne vise plus seulement l’emploi national mais la domination technologique, commerciale et monétaire."),
 dict(name="Richard Baldwin", dates="1958-", courant="Économie internationale", chapters=[24],
      idea="Le commerce est passé du statut d’opportunité à celui de vulnérabilité stratégique",
      oeuvres=["Travaux sur les chaînes de valeur mondiales et le régionalisme"],
      detail="Baldwin résume le renversement contemporain : l’interdépendance était analysée comme une opportunité permettant de bénéficier des avantages comparatifs des partenaires ; elle est désormais lue comme une dépendance potentielle, donc comme une vulnérabilité. Les États cherchent alors à dérisquer leurs échanges — réduire les dépendances dangereuses sans supprimer tous les flux — notamment par le friendshoring, ce qui favorise la constitution de blocs géoéconomiques. Baldwin propose par ailleurs l’image d’un ordre commercial en « système solaire », où de grandes puissances réglementaires deviennent les centres autour desquels gravitent des partenaires reliés par de multiples accords, et illustre en 2008 le « bol de spaghettis » par le cas de l’Amérique latine.",
      phrase="Baldwin donne sa formule au basculement du chapitre : la même interdépendance qui fondait la mondialisation heureuse devient, sans que les flux changent, la matière première de la mondialisation dangereuse."),
 dict(name="Lionel Fontagné", dates="1958-", courant="Économie internationale", chapters=[24],
      idea="Un même individu a des préférences contradictoires face à l’ouverture selon qu’il raisonne en consommateur, en travailleur ou en épargnant",
      oeuvres=["Travaux du CEPII sur le commerce international"],
      detail="Fontagné montre que l’ambiguïté de la société civile face à la mondialisation n’est pas une incohérence mais la conséquence logique de positions multiples : comme consommateur, l’individu bénéficie de produits importés moins chers ; comme travailleur, il peut craindre la concurrence internationale et les délocalisations ; comme épargnant, il peut profiter de l’internationalisation des capitaux. Les préférences collectives à l’égard de l’ouverture sont donc nécessairement instables, ce qui explique que le consensus des années 1990 ait pu se défaire sans que les faits économiques changent brutalement.",
      phrase="Fontagné explique pourquoi l’opinion sur la mondialisation est structurellement ambivalente : ce n’est pas que les citoyens hésitent, c’est qu’ils occupent simultanément des positions aux intérêts opposés."),
 dict(name="Branko Milanovic", dates="1953-", courant="Économie des inégalités", chapters=[24],
      idea="Une « grande transformation » idéologique fait passer du néolibéralisme au « libéralisme de marché national »",
      oeuvres=["Travaux sur les inégalités mondiales et les variétés du capitalisme"],
      detail="Le modèle de l’hypermondialisation reposait sur le néolibéralisme : libéralisation des biens et des services, circulation du travail et surtout libre circulation du capital. Milanovic soutient que ce modèle laisse place à un libéralisme de marché national, c’est-à-dire au maintien d’une logique libérale à l’intérieur des économies et au retour d’une logique mercantiliste dans les relations entre États. La grande transformation contemporaine n’est donc pas la disparition du marché mais sa renationalisation, ce qui constitue une rupture majeure avec le consensus de Washington.",
      phrase="Milanovic nomme précisément le basculement : libéralisme à l’intérieur, mercantilisme à l’extérieur — formule qui interdit de lire la période comme un simple retour du protectionnisme."),
 dict(name="Arnaud Orain", dates="", courant="Histoire de la pensée économique", chapters=[24],
      idea="Le retour du « capitalisme de la finitude » transforme le commerce en jeu à somme nulle",
      oeuvres=["Le Monde confisqué. Essai sur le capitalisme de la finitude (XVIe-XXIe siècle) (2025)"],
      detail="Orain identifie trois manifestations de l’affaiblissement de l’ordre économique libéral : le recul de la liberté commerciale avec le retour du protectionnisme, la remise en cause de la liberté de circulation sur les mers et le développement d’un capitalisme de monopole. La logique commune est la finitude : les ressources sont perçues comme rares, limitées et parfois non reproductibles, de sorte que l’objectif devient de contrôler les actifs rares avant les autres pour obtenir des rentes, quitte à adopter des postures impérialistes. Il distingue trois âges — la période mercantiliste, la première mondialisation et l’impérialisme colonial, puis la réapparition de cette logique après la crise des subprimes et son renforcement après 2020 — et deux formes de finitude aujourd’hui décisives : celle des ressources naturelles et celle des débouchés.",
      phrase="Orain fournit le soubassement matériel du néo-mercantilisme contemporain : si les ressources et les débouchés sont finis, le gain de parts de marché d’un pays devient nécessairement la perte d’un autre."),
 dict(name="Kesslassy et Rodrigues", dates="", courant="Économie internationale", chapters=[24],
      idea="La mondialisation ne disparaît pas, elle devient une « mondialisation fragmentée »",
      oeuvres=["Travaux sur la mondialisation fragmentée (2026)"],
      detail="Les auteurs identifient trois caractéristiques de la nouvelle mondialisation. D’abord la reprise en main du politique sur le marché : là où les FMN influençaient fortement les politiques d’attractivité, les États reprennent le contrôle sur les entreprises et les échanges, et la coordination internationale cède devant les rapports de force. Ensuite le recul de la gouvernance multilatérale au profit de l’unilatéralisme, du bilatéralisme et de la régionalisation, avec une préoccupation commune : la souveraineté. Enfin la captation des ressources stratégiques : les États cherchent moins à produire collectivement des biens publics mondiaux qu’à identifier, sécuriser, contrôler et exploiter les ressources avant leurs concurrents — au risque d’une tragédie des biens communs.",
      phrase="Kesslassy et Rodrigues décrivent le passage d’une gouvernance fondée sur la coordination des interdépendances à une logique de puissance organisée autour de la souveraineté et de la captation des ressources."),
 dict(name="Charles Kindleberger", dates="1910-2003", courant="Économie internationale", chapters=[24],
      idea="La stabilité de l’économie mondiale suppose un leader hégémonique acceptant le coût des biens publics internationaux",
      oeuvres=["La Grande Dépression mondiale, 1929-1939 (1973)",
               "« Dominance and Leadership in the International Economy: Exploitation, Public Goods, and Free Rides » (1981)"],
      detail="Un ordre économique international stable repose sur la fourniture de biens publics internationaux : système monétaire stable, cadre commercial ouvert, liquidités en période de crise, mécanismes de coopération. Mais ces biens profitant à tous, chaque État est tenté de laisser les autres les financer : c’est le problème du passager clandestin, que la matrice du cours formalise — le suiveur qui fait défection obtient 5 tandis que le leader coopérant n’obtient que 3. Seule une puissance dominante, assez puissante pour faire respecter les règles et assez légitime pour être suivie, peut assumer durablement ce coût ; après 1945, les États-Unis, avec environ 60 % de la production mondiale et 70 % des réserves d’or, occupent cette position.",
      phrase="Kindleberger donne au chapitre sa clé d’ensemble : la crise actuelle du multilatéralisme est d’abord une crise d’hégémonie, puisque aucune puissance ne cumule plus aujourd’hui capacité d’imposer les règles et légitimité pour les faire accepter."),
 dict(name="Paul Krugman", dates="1953-", courant="Nouvelle théorie du commerce international", chapters=[24],
      idea="Le GATT repose sur un « mercantilisme éclairé » qui aboutit malgré tout à la libéralisation",
      oeuvres=["Travaux sur la politique commerciale et les négociations multilatérales"],
      detail="Dans les théories traditionnelles, l’importation est le but même de l’échange puisqu’elle permet d’obtenir à moindre coût ce qu’il serait coûteux de produire. Mais dans les négociations du GATT, les États raisonnent politiquement à l’inverse : les exportations sont traitées comme un gain et les importations comme une concession. Krugman qualifie cette logique de mercantilisme éclairé : chaque pays n’ouvre son marché que pour obtenir des débouchés, et c’est précisément ce marchandage réciproque qui produit une libéralisation collective. Le paradoxe est donc fécond : une théorie fausse du gain commercial conduit à une politique commerciale ouverte.",
      phrase="Krugman montre que le multilatéralisme n’a pas fonctionné parce que les États auraient compris Ricardo, mais parce que la réciprocité transforme un raisonnement mercantiliste en libéralisation effective."),
 dict(name="Bela Balassa", dates="1928-1991", courant="Intégration économique", chapters=[24],
      idea="L’intégration économique régionale forme un continuum en cinq étapes",
      oeuvres=["The Theory of Economic Integration (1961)"],
      detail="Balassa distingue cinq niveaux croissants d’intégration : la zone de libre-échange, où les membres suppriment entre eux les droits de douane tout en conservant chacun sa politique commerciale extérieure ; l’union douanière, qui ajoute un tarif extérieur commun ; le marché commun, qui autorise la libre circulation du travail et du capital ; l’union économique et monétaire, qui coordonne les politiques économiques et peut conduire à une monnaie commune ; enfin l’intégration totale, qui unifie les politiques sous une autorité supranationale. Chaque étape ajoute une dimension à la précédente et réduit d’autant l’autonomie économique des États membres.",
      phrase="La typologie de Balassa permet de ne jamais confondre les degrés d’intégration : l’Union européenne est une union douanière et un marché commun, ce qui explique que la France ne fixe pas seule ses droits de douane."),
 dict(name="Jacob Viner", dates="1892-1970", courant="Économie internationale", chapters=[24],
      idea="Une union douanière produit simultanément de la création et du détournement de trafic",
      oeuvres=["The Customs Union Issue (1950)"],
      detail="Viner établit qu’une union régionale n’améliore pas nécessairement le bien-être. Elle crée du trafic lorsqu’une production domestique coûteuse est remplacée par une importation moins chère venant d’un partenaire : l’allocation des ressources s’améliore. Mais elle détourne le trafic lorsque la préférence tarifaire conduit à abandonner un fournisseur extérieur plus efficace au profit d’un partenaire régional moins efficace : le commerce intra-zone augmente alors que l’efficience mondiale diminue. Le bilan d’un accord dépend donc de l’effet qui domine, ce qui interdit de juger un ACR à la seule progression des échanges internes.",
      phrase="Viner fournit le critère d’évaluation de tout accord régional : la hausse du commerce intra-zone ne prouve rien, seule la comparaison entre création et détournement de trafic permet de conclure."),
 dict(name="Robert Lawrence", dates="1949-", courant="Économie internationale", chapters=[24],
      idea="Les accords contemporains passent d’une intégration superficielle à une intégration profonde",
      oeuvres=["Regionalism, Multilateralism and Deeper Integration (1996)"],
      detail="L’intégration superficielle se limite à supprimer les barrières situées aux frontières : droits de douane, quotas, restrictions quantitatives. L’intégration profonde cherche au contraire à rapprocher les règles internes des économies — normes sociales, environnement, droit du travail, concurrence, investissements, propriété intellectuelle, marchés publics, normes sanitaires. Cette distinction explique la transformation des ACR contemporains : l’accord entre l’Union européenne et le Vietnam ne se limite pas aux droits de douane, il engage le Vietnam sur les normes fondamentales du travail et les conventions de l’OIT. Les accords deviennent ainsi des instruments de diffusion de normes.",
      phrase="Lawrence complète Balassa : un accord ne se juge pas seulement au niveau institutionnel atteint, mais à la profondeur réglementaire qu’il impose aux économies partenaires."),
 dict(name="Jagdish Bhagwati", dates="1934-", courant="Économie internationale", chapters=[24],
      idea="La multiplication des accords préférentiels produit un « bol de spaghettis » qui complexifie le commerce",
      oeuvres=["« US Trade Policy: The Infatuation with Free Trade Agreements » (1995)"],
      detail="Chaque accord préférentiel fixe ses propres droits, règles d’origine, normes, exceptions, procédures et mécanismes de règlement. Or un même pays participe simultanément à plusieurs accords : il doit donc respecter plusieurs ensembles de règles qui se superposent. Bhagwati compare ces accords entremêlés à des spaghettis : la régionalisation augmente les coûts administratifs et l’incertitude des entreprises, et peut donc paradoxalement compliquer le commerce qu’elle prétend faciliter. Richard Baldwin illustre cette image en 2008 à partir des accords latino-américains.",
      phrase="Bhagwati identifie le coût caché du régionalisme : ce ne sont plus les droits de douane qui entravent les échanges, mais l’enchevêtrement des règles d’origine que la multiplication des accords impose aux exportateurs."),
 dict(name="Dani Rodrik", dates="1957-", courant="Économie du développement et de la mondialisation", chapters=[24],
      idea="Le trilemme politique de l’économie mondiale : hypermondialisation, démocratie et souveraineté nationale sont incompatibles",
      oeuvres=["Travaux sur le trilemme politique de l’économie mondiale et sur les « good jobs »"],
      detail="On ne peut conserver que deux termes sur trois. Souveraineté et démocratie supposent de limiter l’hypermondialisation, puisque la mobilité du capital contraint la fiscalité et la politique sociale : c’est le compromis de Bretton Woods. Hypermondialisation et souveraineté nationale fragilisent la démocratie, les politiques devant se plier à la discipline des marchés internationaux — la « camisole dorée ». Hypermondialisation et démocratie exigeraient une gouvernance supranationale très approfondie, difficile à construire. Rodrik ajoute une réponse sociale : dans des économies majoritairement tertiaires, la priorité n’est pas la seule réindustrialisation mais l’élévation de la productivité et de la qualité des emplois de services, les « good jobs ».",
      phrase="Rodrik fournit l’armature normative du chapitre : si l’on refuse à la fois la gouvernance mondiale et la perte d’autonomie démocratique, la seule variable d’ajustement restante est le degré d’intégration économique lui-même."),
 dict(name="Sébastien Jean", dates="", courant="Économie internationale", chapters=[24],
      idea="Trois scénarios possibles pour le commerce mondial : continuité sous tensions, guerre froide économique ou réforme de l’OMC",
      oeuvres=["« Le commerce international en crise systémique », L’Économie mondiale 2020 (2019)"],
      detail="Le premier scénario maintient l’OMC comme cadre principal mais avec des tensions sino-américaines persistantes et un recours croissant aux exceptions : droits compensateurs, sanctions ciblées, restrictions temporaires, accords administrés ; les chaînes de valeur ne se réorganisent que dans les secteurs les plus stratégiques. Le deuxième voit les sanctions se multiplier, les chaînes se réorganiser selon les alliances, les pays tiers subir des pressions pour choisir leur camp : c’est la fragmentation géo-économique. Le troisième suppose que le coût du conflit devienne trop élevé et conduise à un compromis sur les subventions industrielles, le statut des pays en développement, les transferts technologiques et le règlement des différends.",
      phrase="Sébastien Jean structure le pronostic : les exceptions deviennent la règle ou restent des exceptions, et c’est le coût perçu du conflit qui décide du basculement."),
 dict(name="M. Bolhuis, J. Chen et B. Kett", dates="", courant="Économie internationale (FMI)", chapters=[24],
      idea="La fragmentation géoéconomique a un coût économique élevé, surtout pour les pays les plus pauvres",
      oeuvres=["« Les coûts de la fragmentation géoéconomique », Finance & Development, FMI (2023)"],
      detail="Les auteurs chiffrent plusieurs scénarios. Un découplage stratégique limité — suppression de certains échanges entre la Russie et le bloc occidental, réduction du commerce technologique entre la Chine et les États-Unis ou l’Union européenne — entraîne déjà une perte permanente d’environ 0,3 % du PIB mondial. Une fragmentation complète en deux blocs, États-Unis et Union européenne d’un côté, Chine et Russie de l’autre, coûte environ 2,3 % du PIB mondial. Une transition brutale, obligeant les entreprises à reconstruire très rapidement leurs chaînes d’approvisionnement, peut atteindre 7 % dans certains scénarios. Les pertes sont particulièrement fortes pour les pays à faible revenu, plus dépendants des importations et moins capables de reconstruire leurs chaînes de valeur.",
      phrase="Bolhuis, Chen et Kett donnent l’ordre de grandeur décisif : la fragmentation n’est pas une simple réorganisation géographique, elle détruit une partie des gains de la spécialisation, et d’abord au détriment des plus pauvres."),
 dict(name="I. Bensidoun et M. Péron", dates="", courant="Économie internationale (CEPII)", chapters=[24],
      idea="L’Union européenne est prise dans un « étau inédit » entre les États-Unis et la Chine",
      oeuvres=["« Quelle place pour l’Europe dans un monde de rapports de force ? », L’Économie mondiale 2027 (2026)"],
      detail="Les États-Unis restent un allié stratégique mais mènent une politique économique de plus en plus ouvertement nationale, mobilisant droits de douane, subventions, politique industrielle et conditions d’accès au marché. La Chine demeure un partenaire commercial majeur tout en devenant un concurrent systémique dans les véhicules électriques, les batteries, les panneaux solaires et les technologies vertes, dont l’Europe a pourtant besoin pour sa transition. L’Union dispose pourtant d’atouts réels : un marché de 450 millions de consommateurs, une puissance normative, des industries avancées — chimie, pharmacie, automobile, aéronautique, spatial, défense — et un capital humain qualifié. Sa difficulté est institutionnelle : construite pour un ordre fondé sur les règles et la concurrence libre et non faussée, elle peine à transformer ses ressources en capacité d’action stratégique.",
      phrase="Bensidoun et Péron formulent le diagnostic européen le plus utilisable en copie : l’Union n’a pas un problème de puissance mais de conversion de sa puissance, parce qu’elle a été construite pour un autre monde."),
 dict(name="David Ricardo", dates="1772-1823", courant="Classique", chapters=[24],
      idea="Les gains à l’échange proviennent de la spécialisation selon les avantages comparatifs",
      oeuvres=["Principes de l’économie politique et de l’impôt (1817)"],
      detail="Le chapitre mobilise Ricardo comme point de comparaison : dans les théories traditionnelles, l’ouverture permet la spécialisation, donc une meilleure allocation des ressources, donc un gain à l’échange, et l’importation est l’élément essentiel du libre-échange puisqu’elle procure à moindre coût ce qu’il serait coûteux de produire nationalement. Cette logique éclaire par contraste celle des négociations du GATT, où les États traitent au contraire les importations comme des concessions : c’est l’écart que Krugman nomme mercantilisme éclairé.",
      phrase="Ricardo sert ici de repère négatif : la négociation commerciale ne suit pas la théorie du commerce, et c’est précisément pour cela que le multilatéralisme a eu besoin de la réciprocité."),
 dict(name="Modèle HOS (Heckscher, Ohlin, Samuelson)", dates="1919-1941", courant="Néoclassique", chapters=[24],
      idea="La spécialisation internationale dépend des dotations relatives en facteurs de production",
      oeuvres=["Heckscher (1919), Ohlin (1933), Samuelson (1941)"],
      detail="Le chapitre rappelle le modèle HOS pour situer la logique des négociations commerciales : dans ce cadre, l’ouverture conduit chaque pays à se spécialiser selon ses dotations relatives, ce qui améliore l’allocation mondiale des ressources et produit des gains à l’échange. Ces théories expliquent pourquoi l’importation est économiquement souhaitable, alors que les négociations multilatérales la traitent politiquement comme une concession arrachée.",
      phrase="Le modèle HOS fournit la justification théorique de l’ouverture, que le fonctionnement concret des rounds du GATT contredit dans sa formulation tout en la réalisant dans ses effets."),
 dict(name="John Nash", dates="1928-2015", courant="Théorie des jeux", chapters=[24],
      idea="L’équilibre de Nash peut être collectivement sous-optimal, ce qui justifie la coordination internationale",
      oeuvres=["Travaux fondateurs sur les équilibres non coopératifs"],
      detail="Le chapitre mobilise l’équilibre de Nash pour expliquer la nécessité d’une gouvernance mondiale. En l’absence de coordination, chaque État a intérêt à laisser les autres supporter le coût des biens publics mondiaux : les comportements de passager clandestin conduisent à un équilibre où personne n’a intérêt à dévier unilatéralement, mais où la production du bien collectif est insuffisante. L’établissement de règles de bonne conduite internationales vise précisément à sortir de cet équilibre sous-optimal, et la matrice de Kindleberger en donne une illustration chiffrée.",
      phrase="L’équilibre de Nash sous-optimal est l’argument théorique décisif en faveur de la gouvernance mondiale : ce n’est pas l’irrationalité des États qui empêche la coopération, c’est au contraire leur rationalité individuelle."),
 dict(name="Franklin Delano Roosevelt", dates="1882-1945", courant="New Deal", chapters=[24],
      idea="L’Agricultural Adjustment Act de 1933 inaugure le soutien public durable aux revenus agricoles",
      oeuvres=["Agricultural Adjustment Act (1933)"],
      detail="La crise des années 1930 provoque aux États-Unis une forte dégradation des revenus agricoles. Dans le cadre du New Deal, Roosevelt met en place des mesures de soutien à l’agriculture, dont l’Agricultural Adjustment Act de 1933 constitue l’étape majeure. La politique agricole américaine repose ensuite sur des aides aux agriculteurs, des mécanismes de soutien des prix et des dispositifs de stabilisation des revenus, structurés par les Farm Bills successifs. Cette matrice inspire la PAC européenne de 1962 et explique la persistance d’une exception agricole au sein du système commercial multilatéral.",
      phrase="L’AAA de 1933 montre que l’exception agricole n’est pas un accident des négociations commerciales mais l’héritage d’une politique de stabilisation des revenus antérieure de quinze ans au GATT."),
]
